def solve(n):
    dp = [0] * (n + 1)
    dp[0] = 0
    dp[1] = 0
    dp[2] = 1
    for i in range(3, n + 1):
        dp[i] = max(dp[i - 1], dp[i - 2] + 1)
        if i % 3 == 0:
            dp[i] = max(dp[i], dp[i // 3] + 1)
    return "First" if dp[n] % 2 == 0 else "Second"

