    for i in range(n):
        dp[i][i] = 1
        for j in range(i):
            if s[i] == s[j]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])
    return s[dp[n-1][n-1]:n-1:-1]

def minCost(s):
