def minLength(s):
    # Initialize the length of the minimized string
    minimized_length = len(s)

    # Iterate through the string
    for i in range(len(s)):
        # If the character at index i is 'a', we can start by selecting it
        if s[i] == 'a':
            # Initialize the minimum distance to the left and right
            min_left = float('inf')
            min_right = float('inf')

            # Iterate through the string
            for j in range(i, -1, -1):
                # If the character at index j is 'a', we can delete it
                if s[j] == 'a':
                    min_left = min(min_left, j)

            for j in range(i + 1, len(s)):
                # If the character at index j is 'a', we can delete it
                if s[j] == 'a':
                    min_right = min(min_right, j)

            # If the minimum distance to the left and right is less than the current minimized length, update the minimized length
            minimized_length = min(minimized_length, i - min_left + min_right + 1)

    return minimized_length

def canVisitAllRooms(self, rooms):
    visited = set()
    for room in rooms[0]:
        visited.add(room)
    stack = [0]
    while stack:
        room = stack.pop()
        for neighbor in rooms[room]:
            if neighbor not in visited:
                visited.add(neighbor)
                stack.append(neighbor)
    return len(visited) == len(rooms)

