def is_possible_to_win(S, T):
    def dfs(i, j, S, T):
        if i == len(S) and j == len(T):
            return True
        if i < len(S) and j < len(T) and S[i] == T[j]:
            return dfs(i + 1, j + 1, S, T)
        if i < len(S) and j < len(T) and S[i] != T[j]:
            return dfs(i + 1, j, S, T) or dfs(i, j + 1, S, T)

