def solve(H, W, T):
    # Check if it is possible to reach the goal square in at most T moves
    if T > 2 * W:
        return -1

    # Initialize the grid
    grid = [['.' for _ in range(W)] for _ in range(H)]
    grid[0][0] = 'S'
    grid[H-1][W-1] = 'G'
    grid[H-1][0] = '#'
    grid[0][W-1] = '#'
    grid[1][1] = 'o'

    # Initialize the visited grid
    visited = [[False for _ in range(W)] for _ in range(H)]
    visited[0][0] = True

    # Check if it is possible to reach the goal square in at most T moves
    if not is_possible(grid, visited, T):
        return -1

    # Find the maximum number of candy squares that can be visited on the way to the goal square
    max_candy = 0
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'o' and not visited[i][j]:
                max_candy = max(max_candy, count_candy(grid, visited, i, j, T))

    return max_candy

def is_possible(grid, visited, T):
    # Check if it is possible to reach the goal square in at most T moves
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'o' and not visited[i][j]:
                return False

    return True

def count_candy(grid, visited, i, j, T):
    # Count the number of candy squares that can be visited on the way to the goal square
    candy_count = 0
    while True:
        if i == 0 or j == 0 or i == H-1 or j == W-1:
            break
        if grid[i][j] == 'o' and not visited[i][j]:
            candy_count += 1
            visited[i][j] = True
        if T == 0:
            break
        i, j = i - 1, j - 1
        T -= 1

    return candy_count

