def find_cycle(n, edges):
    # Create a graph with n vertices and n edges
    graph = {i: [] for i in range(n)}
    for i, j in edges:
        graph[i].append(j)
        graph[j].append(i)

    # Use depth-first search to find a cycle
    def dfs(node, visited, stack):
        visited[node] = True
        stack.append(node)
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor, visited, stack)
            elif neighbor in stack:
                return True
        stack.pop()

    # Find a cycle
    for i in range(n):
        visited = [False] * n
        stack = [i]
        while stack:
            node = stack.pop()
            if dfs(node, visited, stack):
                return True
        if not visited[i]:
            return True
    return False

def print_cycle(n, edges):
    cycle = find_cycle(n, edges)
    if cycle:
        print(len(cycle))
        for node in cycle:
            print(node)
    else:
