def max_weight_edges(n, edges):
    # Create a graph with n vertices
    graph = [[0]*n for _ in range(n)]

    # Add edges to the graph
    for i in range(n):
        for j in range(i+1, n):
            graph[i][j] = edges[i][j]
            graph[j][i] = edges[i][j]

    # Use dynamic programming to find the maximum weight of a subset of edges
    dp = [0]*n
    for i in range(n):
        dp[i] = edges[i][i]

    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                dp[j] = max(dp[j], dp[i] + dp[k] + graph[i][j] + graph[j][k])

    return dp[n-1]

