def minimum_cost(n, m, k, edges):
    # Create a graph
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u-1].append((v-1, w))
        graph[v-1].append((u-1, w))

    # Perform Kruskal's algorithm
    def kruskal(graph, n):
        edges = []
        for u in range(n):
            for v, w in graph[u]:
                edges.append((u, v, w))
        edges.sort()
        result = []
        for u, v, w in edges:
            if len(result) < n-1:
                result.append((u, v, w))
        return result

    # Find the minimum cost of a spanning tree
    result = kruskal(graph, n)
    cost = sum(w % k for u, v, w in result)
    return cost

