def solve(N, M, K, C, A):
    # Create an empty graph
    graph = [[] for _ in range(N + 1)]

    # Add edges to the graph
    for i in range(M):
        S = set(A[i])
        for u, v, w in zip(A[i + 1], A[i + 2], C[i:i + 2]):
            if u in S and v in S:
                graph[u].append((v, w))
                graph[v].append((u, w))

    # Find the minimum spanning tree
    def find_mst(graph):
        parent = [i for i in range(len(graph))]
        key = [float('inf')] * len(graph)
        key[0] = 0
        mst_weight = 0
        for _ in range(len(graph) - 1):
            u = find_min(parent, key)
            mst_weight += key[u]
            for v, w in graph[u]:
                if v not in parent or key[u] + w < key[v]:
                    parent[v] = u
                    key[v] = key[u] + w
        return mst_weight

    def find_min(parent, key):
        min_val = float('inf')
        min_index = -1
        for i in range(len(parent)):
            if parent[i] != -1 and key[i] < min_val:
                min_val = key[i]
                min_index = i
        return min_index

    # Check if the graph is connected
    def is_connected(graph):
        visited = [False] * (N + 1)
        queue = [0]
        while queue:
            u = queue.pop(0)
            if not visited[u]:
                visited[u] = True
                for v, w in graph[u]:
                    if not visited[v]:
                        queue.append(v)
        return all(visited)

    # Find the total weight of the edges in a minimum spanning tree
    mst_weight = find_mst(graph)
    if is_connected(graph):
        return mst_weight
    else:
        return -1

