def solve(N):
    # Initialize the game board
    board = [0] * N
    for i in range(N):
        board[i] = (i + 1, i + 1)

    # Function to check if a player can make a move
    def can_move(player):
        for i in range(N):
            if board[i][0] == board[i][1] or board[i][0] == board[i][2] or board[i][1] == board[i][2]:
                return True
        return False

    # Function to perform a move
    def perform_move(player):
        for i in range(N):
            if board[i][0] == board[i][1] or board[i][0] == board[i][2] or board[i][1] == board[i][2]:
                board[i] = (board[i][0], board[i][2])
                return True
        return False

    # Function to determine the winner
    def determine_winner(player):
        for i in range(N):
            if board[i][0] == board[i][1] or board[i][0] == board[i][2] or board[i][1] == board[i][2]:
                return player
        return None

    # Determine the winner
    if can_move(1):
        return determine_winner(1)
    else:
        return determine_winner(2)

