def solve(N, T, A):
    # Initialize the grid
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the given values
    for i in range(N):
        for j in range(N):
            grid[i][j] = N * (i - 1) + j

    # Mark the cells with the given values
    for i in range(T):
        grid[A[i] - 1][i] = 1

    # Check for Bingo
    for i in range(N):
        if all(grid[i][j] == 1 for j in range(N)):
            return i + 1

    # If Bingo is not achieved within T turns, return -1
    return -1

