def minBoxes(apple, capacity):
    n = len(apple)
    m = len(capacity)
    dp = [[float('inf')] * (max(capacity) + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = 0
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            for k in range(1, max(capacity[j - 1], apple[i - 1]) + 1):
                dp[i][k] = min(dp[i][k], dp[i - 1][k])
                if k >= apple[i - 1]:
                    dp[i][k] = min(dp[i][k], dp[i - 1][k - apple[i - 1]] + 1)
    return dp[n][max(capacity)]

def shortestSubstrings(arr):
    result = []
    for i in range(len(arr)):
        substrings = set()
        for j in range(i, len(arr)):
            substrings.add(arr[j])
            if len(substrings) == len(arr):
                result.append(arr[i][:j-i+1])
                break
        else:
            result.append("")
    return result

def checkSubstring(s):
    for i in range(len(s)):
        if s[i:i+2] in s[::-1]:
            return True
    return False

def countSubstrings(s, c):
    count = 0
    for i in range(len(s)):
        if s[i] == c:
            count += 1
            for j in range(i+1, len(s)):
                if s[j] == c:
                    count += 1
    return count

def minMoves(nums, k, maxChanges):
    n = len(nums)
    dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            dp[i][j] = min(dp[i - 1][j], dp[i - 1][j - 1] + nums[i - 1])
            if j - maxChanges >= 0:
                dp[i][j] = min(dp[i][j], dp[i - 1][j - maxChanges] + nums[i - 1])
    return dp[n][k]

def maxLength(s):
    # Create a set to store the characters and their counts
    char_counts = set()
    max_length = 0

    # Iterate through the string
    for char in s:
        # If the character is already in the set, it means it has two occurrences
        if char in char_counts:
            char_counts.remove(char)
        else:
            char_counts.add(char)

        # If the set is empty, it means the current substring has no occurrences of any character
        if not char_counts:
            max_length = max(max_length, len(s))

    return max_length

def minOperations(k):
    if k <= 1:
        return 0
    if k % 2 == 0:
        return 1
    if k % 3 == 0:
        return 2
    if k % 5 == 0:
        return 3
    if k % 7 == 0:
        return 4
    if k % 11 == 0:
        return 5
    return 6

def longestCommonSuffix(wordsContainer, wordsQuery):
    def find_common_suffix(word):
        for i in range(len(word)):
            for j in range(i+1, len(word)):
                if word[i:j+1] == word[i:j+1][::-1]:
                    return word[i:j+1]
        return ""

    ans = []
    for i, word in enumerate(wordsQuery):
        common_suffix = find_common_suffix(word)
        if common_suffix:
            ans.append(wordsContainer.index(common_suffix))
        else:
            ans.append(wordsContainer.index(word))
    return ans

def sum_of_digits(x):
    if x % sum(int(digit) for digit in str(x)) == 0:
        return sum(int(digit) for digit in str(x))
    else:
        return -1

def countAlternatingSubarrays(nums):
    count = 0
    for i in range(len(nums)):
        if i == 0:
            count += nums[i]
        else:
            if nums[i] != nums[i-1]:
                count += 1
    return count

def minMaxDistance(points):
    n = len(points)
    max_distance = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            distance = abs(points[i][0] - points[j][0]) + abs(points[i][1] - points[j][1])
            max_distance = min(max_distance, distance)
    return max_distance

def maxLength(nums):
    n = len(nums)
    dp = [0]*n
    dp[0] = 1
    max_len = 1
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)
            else:
                dp[i] = max(dp[i], dp[j] + 1)
        max_len = max(max_len, dp[i])
    return max_len

def smallestStringWithSwaps(s, k):
    n = len(s)
    char_freq = [0] * 26
    for i in range(n):
        char_freq[ord(s[i]) - ord('a')] += 1

    char_freq_sorted = sorted(char_freq)
    char_freq_sorted.reverse()

    res = [0] * n
    for i in range(n):
        res[i] = char_freq_sorted[i]

    return ''.join(chr(i + ord('a')) for i in res)

def prime_distance(nums):
    primes = [True] * (max(nums) + 1)
    primes[0] = primes[1] = False
    for i in range(2, int(max(nums)**0.5) + 1):
        if primes[i]:
            for j in range(i*i, max(nums) + 1, i):
                primes[j] = False
    return max(abs(i - j) for i, j in enumerate(nums) if primes[j])

