def min_replace_string(s):
    # Initialize the cost array
    cost = [0] * len(s)

    # Initialize the cost array
    for i in range(1, len(s)):
        if s[i] == '?':
            cost[i] = cost[i-1] + 1
        else:
            cost[i] = cost[i-1]

    # Initialize the minimum cost
    min_cost = cost[0]

    # Initialize the minimum cost string
    min_cost_string = s[0]

    # Iterate over the string
    for i in range(1, len(s)):
        # If the current character is '?'
        if s[i] == '?':
            # Update the cost and the minimum cost
            cost[i] = cost[i-1] + 1
            if cost[i] < min_cost:
                min_cost = cost[i]
                min_cost_string = s[i]
        # If the current character is not '?'
        else:
            # Update the cost and the minimum cost
            cost[i] = cost[i-1]
            if cost[i] < min_cost:
                min_cost = cost[i]
                min_cost_string = s[i]

    return min_cost_string

def sumOfPower(nums, k):
    mod = 10**9 + 7
    n = len(nums)
    dp = [[0]*(k+1) for _ in range(n+1)]
    for i in range(n+1):
        dp[i][0] = 1
    for i in range(1, n+1):
        for j in range(1, k+1):
            dp[i][j] = (dp[i-1][j] + dp[i-1][j-nums[i-1]]) % mod
    return sum(dp[n][j] for j in range(1, k+1))

def min_levels_to_win(possible):
    n = len(possible)
    dp = [0] * (n + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        if possible[i - 1] == 0:
            dp[i] = dp[i - 1]
        else:
            dp[i] = max(dp[i - 1], dp[i - 2] + 1)
    return n - dp[n]

def sumOfSubsequenceWeights(nums, k):
    MOD = 10**9 + 7
    dp = [0] * (k + 1)
    dp[0] = 0
    for num in nums:
        for i in range(k, num - 1, -1):
            dp[i] = (dp[i] + dp[i - num]) % MOD
    return dp[k]

