def findMinX(nums1, nums2):
    # Find the frequency of each element in nums1
    freq1 = {}
    for num in nums1:
        freq1[num] = freq1.get(num, 0) + 1

    # Find the frequency of each element in nums2
    freq2 = {}
    for num in nums2:
        freq2[num] = freq2.get(num, 0) + 1

    # Find the difference between the frequencies
    diff = 0
    for num in freq1:
        if num in freq2:
            diff += freq1[num] - freq2[num]

    # Find the minimum x such that nums1 can become equal to nums2 by adding x to each element
    x = 0
    while True:
        if diff == 0:
            return x
        x += 1
        diff -= freq1[x]

def minArray(n, x):
    nums = [0] * n
    for i in range(n - 1):
        nums[i + 1] = nums[i] * 2 + x
    return nums[n - 1]

def is_valid_word(word):
    # Check if word has at least 3 characters
    if len(word) < 3:
        return False

    # Check if word contains only digits and English letters
    if not word.isdigit() and not word.isalpha():
        return False

    # Check if word contains at least one vowel
    vowels = 'aeiouAEIOU'
    if word.lower() not in vowels:
        return False

    # Check if word contains at least one consonant
    consonants = 'bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ'
    if word.lower() not in consonants:
        return False

    return True

def minOperations(word, k):
    n = len(word)
    k = k
    res = 0
    for i in range(n):
        if i % k == 0:
            res += 1
            if i + k - 1 < n:
                res += word[i + k - 1] == word[i]
    return res

def minLength(s):
    # Create a dictionary to store the count of each character
    char_count = {}
    for char in s:
        char_count[char] = char_count.get(char, 0) + 1

    # Find the minimum length of the string t
    min_length = float('inf')
    for char in char_count:
        if char_count[char] > 1:
            min_length = min(min_length, len(s) - char_count[char])

    return min_length

def minCost(nums, cost1, cost2):
    n = len(nums)
    dp = [[0] * (cost2 + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = 0
    for i in range(1, n + 1):
        for j in range(1, min(i, cost2) + 1):
            dp[i][j] = dp[i - 1][j] + cost1
            if j >= nums[i - 1]:
                dp[i][j] = min(dp[i][j], dp[i - 1][j - nums[i - 1]] + cost2)
    return dp[n][cost2] % (10**9 + 7)

