def stableArrays(zero, one, limit):
    mod = 10**9 + 7
    dp = [0] * (one + 1)
    dp[0] = 1
    for i in range(zero):
        dp[i + 1] = (dp[i] * (one - i) * (i + 1)) % mod
    for i in range(one):
        dp[i + 1] = (dp[i] * (zero - i) * (i + 1)) % mod
    return sum(dp) % mod

def getPermutationDifference(s, t):
    # Create a dictionary to store the frequency of each character in s
    freq_s = {}
    for char in s:
        if char in freq_s:
            freq_s[char] += 1
        else:
            freq_s[char] = 1

    # Create a dictionary to store the frequency of each character in t
    freq_t = {}
    for char in t:
        if char in freq_t:
            freq_t[char] += 1
        else:
            freq_t[char] = 1

    # Calculate the permutation difference
    permutation_difference = 0
    for char in s:
        if char in freq_t:
            permutation_difference += abs(freq_s[char] - freq_t[char])
        else:
            permutation_difference += abs(freq_s[char])

    return permutation_difference

def is_special_array(nums):
    for i in range(len(nums) - 1):
        if nums[i] % 2 == nums[i + 1] % 2:
            return False
    return True

def sumOfDigitDifferences(nums):
    total_sum = 0
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            diff = len(set(str(nums[i])).intersection(str(nums[j])))
            total_sum += diff
    return total_sum

def totalWays(k):
    if k == 0:
        return 1
    elif k == 1:
        return 2
    else:
        return totalWays(k - 1) + totalWays(k - 2) + totalWays(k - 4)

def countGoodPairs(nums1, nums2, k):
    count = 0
    for i in range(len(nums1)):
        for j in range(len(nums2)):
            if nums1[i] % k == 0 and nums2[j] % k == 0:
                count += 1
    return count

def compress(word):
    comp = ""
    for i in range(len(word)):
        if i == 0:
            comp += word[i]
        else:
            if word[i] == word[i-1]:
                comp += str(len(word[:i])) + word[i]
            else:
                comp += word[i]
    return comp

def powerful_array(queries):
    big_nums = [1]
    for i in range(1, 1000000):
        big_nums.append(big_nums[-1] * 2)
    result = []
    for from_i, to_i, mod_i in queries:
        product = 1
        for i in range(from_i, to_i + 1):
            product *= big_nums[i]
        result.append(product % mod_i)
    return result

def xor_twice(nums):
    xor_result = 0
    for num in nums:
        if nums.count(num) == 2:
            xor_result ^= num
    return xor_result

def query_indices(nums, queries, x):
    result = []
    for i, num in enumerate(nums):
        if num == x:
            result.append(i)
        elif num > x:
            break
    return result
